import React, { useEffect, useRef, useMemo } from 'react';
import { motion, useAnimation, AnimationControls, Variants } from 'framer-motion';
import { useAnimation as useAnimationContext, useAnimationId } from './AnimationContext';

interface AnimatedTextProps {
  text: string;
  className?: string;
  element?: 'p' | 'h1' | 'h2' | 'h3' | 'h4' | 'span' | 'div' | 'li' | 'a';
  preserveWhitespace?: boolean;
  onAnimationComplete?: () => void;
  // Animation timing parameters
  baseDelay?: number;
  randomVariation?: number;
  punctuationPause?: number;
  animateOnMount?: boolean;
}

/**
 * AnimatedText - Reliable character-by-character animation with organic timing
 * 
 * This component only animates ONCE and properly completes its animation
 * It includes randomized timing with longer pauses for punctuation
 */
const AnimatedText: React.FC<AnimatedTextProps> = ({
  text,
  className = '',
  element = 'span',
  preserveWhitespace = false,
  onAnimationComplete,
  baseDelay = 0.06,
  randomVariation = 0.03,
  punctuationPause = 0.25,
  animateOnMount = true,
}) => {
  // Animation state tracking
  const hasAnimatedRef = useRef(false);
  const controls = useAnimation();

  // Generate unique ID for this animation
  const animationId = useAnimationId('text');

  // Access animation context
  const { registerAnimation, parentId } = useAnimationContext();

  // Calculate randomized delays for each character
  const characterDelays = useMemo(() => {
    if (!text) return [];

    const delays: number[] = [];
    let cumulativeDelay = 0;

    for (let i = 0; i < text.length; i++) {
      const char = text[i];

      // Add randomness to the base delay
      const randomOffset = (Math.random() * 2 - 1) * randomVariation;
      let charDelay = baseDelay + randomOffset;

      // Add extra pause after punctuation
      if (i > 0 && /[.,!?;:]/.test(text[i-1])) {
        charDelay += punctuationPause;
      }

      // Add occasional slightly longer pause to simulate human typing rhythm
      if (Math.random() > 0.9) {
        charDelay += 0.12;
      }

      cumulativeDelay += charDelay;
      delays.push(cumulativeDelay);
    }

    return delays;
  }, [text, baseDelay, randomVariation, punctuationPause]);

  // Define the animation start function
  const startAnimation = async (): Promise<void> => {
    if (hasAnimatedRef.current) return Promise.resolve();

    return new Promise<void>((resolve) => {
      controls.start("visible")
        .then(() => {
          hasAnimatedRef.current = true;
          if (onAnimationComplete) {
            onAnimationComplete();
          }
          resolve();
        })
        .catch(error => {
          console.error("Animation error:", error);
          resolve();
        });
    });
  };

  // Register this animation with the context
  useEffect(() => {
    registerAnimation(animationId, startAnimation);

    // Start animation on mount if specified
    if (animateOnMount && !hasAnimatedRef.current) {
      startAnimation();
    }

    return () => {
      // Cleanup on unmount
      controls.stop();
    };
  }, [registerAnimation, animationId, animateOnMount]);

  // If text is empty, render nothing
  if (!text || text.length === 0) {
    return null;
  }

  // Character animation variant - enhanced for more visibility
  const charVariant: Variants = {
    hidden: { 
      opacity: 0,
      y: 5,
      scale: 0.9,
      filter: "blur(2px)",
      display: 'inline-block'
    },
    visible: (i: number) => ({
      opacity: 1,
      y: 0,
      scale: 1,
      filter: "blur(0px)",
      display: 'inline-block',
      transition: { 
        duration: 0.12,
        ease: "easeOut",
        delay: characterDelays[i] || 0
      }
    })
  };

  // Create the characters as motion.span elements
  const animatedCharacters = Array.from(text).map((char, index) => (
    <motion.span
      key={`${animationId}-${index}`}
      custom={index}
      variants={charVariant}
      initial="hidden"
      animate={controls}
      style={{ 
        display: 'inline-block',
        whiteSpace: 'pre',
        position: 'relative'
      }}
    >
      {char === ' ' ? '\u00A0' : char}
    </motion.span>
  ));

  // Render the appropriate element with the animated characters
  const commonProps = {
    className: `animated-text ${className}`,
    style: { 
      whiteSpace: preserveWhitespace ? 'pre-wrap' as const : 'normal' as const,
      display: 'inline-block'
    }
  };

  switch (element) {
    case 'h1':
      return <motion.h1 {...commonProps}>{animatedCharacters}</motion.h1>;
    case 'h2':
      return <motion.h2 {...commonProps}>{animatedCharacters}</motion.h2>;
    case 'h3':
      return <motion.h3 {...commonProps}>{animatedCharacters}</motion.h3>;
    case 'h4':
      return <motion.h4 {...commonProps}>{animatedCharacters}</motion.h4>;
    case 'li':
      return <motion.li {...commonProps}>{animatedCharacters}</motion.li>;
    case 'a':
      return <motion.a {...commonProps}>{animatedCharacters}</motion.a>;
    case 'div':
      return <motion.div {...commonProps}>{animatedCharacters}</motion.div>;
    case 'p':
      return <motion.p {...commonProps}>{animatedCharacters}</motion.p>;
    case 'span':
    default:
      return <motion.span {...commonProps}>{animatedCharacters}</motion.span>;
  }
};

export default AnimatedText;
